from scipy.optimize import least_squares
y=dA_dt
tot=np.sum((y-y.mean())**2)
cands={
 'A1': (lambda p: -p[0]*np.exp(-p[1]*t)*A**p[2] + p[3]*A**p[4]*np.exp(-p[5]*t), 6),
 'A3': (lambda p: -p[0]*A/(p[1]+A)*(1+p[2]*t) + p[3]*A**p[4]*t**p[5], 6),
 'A6': (lambda p: -p[0]*A/(p[1]+A)*np.exp(-p[2]*t)+p[3]*(A**p[4]) -p[5]*t*A, 6),
}
rng=np.random.default_rng(1)
for k,(f,n) in cands.items():
    best=(1e9,None)
    for s in range(12):
        p0=rng.normal(0,1.0,n)
